import{_ as e,o as n,c as t,a as i}from"./app.60a5b4a9.js";var a="/aktivitaeten/BDM-2026-09/00_09-2026.jpg",r="/aktivitaeten/BDM-2026-09/01_09-2026.jpg",s="/aktivitaeten/BDM-2026-09/02_09-2026.jpg",d="/aktivitaeten/BDM-2026-09/03_09-2026.jpg",o="/aktivitaeten/BDM-2026-09/04_09-2026.jpg",h="/aktivitaeten/BDM-2026-09/05_09-2026.jpg",l="/aktivitaeten/BDM-2026-09/06_09-2026.jpg",c="/aktivitaeten/BDM-2026-09/07_09-2026.jpg",g="/aktivitaeten/BDM-2026-09/08_09-2026.jpg",m="/aktivitaeten/BDM-2026-09/09_09-2026.jpg",p="/aktivitaeten/BDM-2026-09/10_09-2026.jpg",u="/aktivitaeten/BDM-2026-09/11_09-2026.jpg",_="/aktivitaeten/BDM-2026-09/12_09-2026.jpg",B="/aktivitaeten/BDM-2026-09/13_09-2026.jpg",v="/aktivitaeten/BDM-2026-09/14_09-2026.jpg",b="/aktivitaeten/BDM-2026-09/15_09-2026.jpg",k="/aktivitaeten/BDM-2026-09/16_09-2026.jpg",M="/aktivitaeten/BDM-2026-09/17_09-2026.jpg";const f={},D=i('<h1 id="bilder-des-monats-september-2026" tabindex="-1"><a class="header-anchor" href="#bilder-des-monats-september-2026" aria-hidden="true">#</a> Bilder des Monats September 2026</h1><hr><p>Heute das trockene Wetter ausgenutzt und DE-1118 \u201EAltdorfer Wald Flora and Fauna Reserve \u201E aktiviert. Zum Einsatz kam der Xiegu G90 und die MC-750 Antenne. Trotz der widrigen Bedingungen (viel QSB) und \u201Enur\u201C 20 Watt konnte ich in einer ca. 30 min\xFCtigen \xD6ffnung 3 QSOs mit Australien ins Log bekommen.</p><p><img src="'+a+'" alt="Bilder des Monats"><img src="'+r+'" alt="Bilder des Monats"></p><hr><p>DB7GKA am 19.09.2026 bei der CW-Aktivierung der POTA-Referenzen DE-0945 Th\xFCringenweg National Recreation Trail und DE-1176 An den Ziegenb\xF6cken Flora and Fauna Reserve. Vor der Sitzbank befindet sich das Sumpfgebiet &quot;Rote Pf\xFCtze&quot; und hinter der Sitzbank geht der Th\xFCringenweg vorbei. Als Antenne fungierte eine 12,5 Meter End-Fed-Random-Wire die mit einen 1:9-UnUn gespeist wurde.</p><p><img src="'+s+'" alt="Bilder des Monats"><img src="'+d+'" alt="Bilder des Monats"><img src="'+o+'" alt="Bilder des Monats"><img src="'+h+'" alt="Bilder des Monats"><img src="'+l+'" alt="Bilder des Monats"><img src="'+c+'" alt="Bilder des Monats"><img src="'+g+'" alt="Bilder des Monats"></p><hr><p>Ich hatte heute die Funkaufsicht in DE-0825 bei Augustdorf in Ostwestfalen - Richtig klasse Spot mit einer Bank als Hochsitz auf einer kleinen Anh\xF6he und Blick \xFCber den Wald. Weit und breit war keine Menschenseele unterwegs und ich konnte mal wieder richtig Funkbetrieb ohne Zwischenfragen machen.</p><p>Auf 40m hatte ich recht schnell ein sch\xF6nes Pileup, bis dann der Splatter zu viel wurde und zum Schluss auf meiner QRG nur noch polnisch gesprochen wurde. 20m brachte neben einigen Europa-Kontakten auch ein QSO mit der US-Westk\xFCste. Das war komplett Grasnarbe, aber der andere OM hatte nicht aufgegeben und nach bestimmt 10 Versuchen konnte ich sein Callsign korrekt aufnehmen.</p><p>Kurz vorm Abbauen hab ich noch mal \xFCbers 17m-Band gedreht und konnte dort einige Stationen h\xF6ren, also hab ich es auch probiert - das brachte dann drei weitere US-Kontakte. Dann wollte ich es noch einmal wissen und habe 15m probiert. Nach einigen erfolglosen CQ-Rufen konnte ich dann noch 2 Stationen aus Wisconsin recht gut h\xF6rbar in mein Log aufnehmen. Mit 73 QSOs in der Tasche ging es dann wieder heimw\xE4rts.</p><p>Yaesu FT-891 (100W), EFHW (Spooltenna-Variante, Eigenbau) mit 20m Draht als Inverted-V durch einen Baum gespannt.</p><p>(DL9CE)</p><p><img src="'+m+'" alt="Bilder des Monats"><img src="'+p+'" alt="Bilder des Monats"><img src="'+u+'" alt="Bilder des Monats"></p><hr><p>Nachdem ich am Nachmittag meinen Sohn zur Kindergeburtstagsfeier gebracht hatte, habe ich die dadurch gewonnene freie Zeit gleich genutzt, um meinen POTA-Hauspark DE-0546 zu aktivieren. Die Anh\xF6he im s\xFCdwestlichen Bereich des Parks hat einen tollen Blick \xFCber die ehemalige Landebahn und die Beachvolleyballpl\xE4tze geboten. Die Bedingungen waren ziemlich wechselhaft und haben teilweise f\xFCr heftiges QSB gesorgt.</p><p>vy 73 de DB7GKA</p><p><img src="'+_+'" alt="Bilder des Monats"><img src="'+B+'" alt="Bilder des Monats"><img src="'+v+'" alt="Bilder des Monats"><img src="'+b+'" alt="Bilder des Monats"></p><hr><p>Die sp\xE4tabendliche Aktivierung der POTA-Referenz DE-1152 Perlacher Forst beim Hirschbrunnen mit 30 CW-QSOs auf den B\xE4ndern 80, 40 und 20 Meter hat sehr viel Spass gemacht. Zum Einsatz kam eine EFHW mit 20 Meter Draht und 1:49-UnUn sowie der Yaesu FT-891 als TRX.</p><p>Trotz der Verwendung einer f\xFCr 80 Meter nichtresonanten Antenne, die f\xFCr das Band auch noch viel zu niedrig hing, kamen mit Tunereinsatz sowie 90 Watt Sendeleistung dort doch einige Stationen ins Log. Auf 20 Meter haben die 90 Watt ebenfalls f\xFCr einige Verbindungen nach Nordamerika gesorgt. Das 40-Meter-Band hat wie immer zuverl\xE4ssig mitteleurop\xE4ische Stationen ins Log gebracht.</p><p>73 DB7GKA</p><p><img src="'+k+'" alt="Bilder des Monats"><img src="'+M+'" alt="Bilder des Monats"></p>',23),w=[D];function S(z,A){return n(),t("div",null,w)}var E=e(f,[["render",S],["__file","2026-09-30-Bilder-Des-Monats-September.html.vue"]]);export{E as default};
